import{_ as t,o,c as n,a5 as s}from"./chunks/framework.BvXk9IVy.js";const h=JSON.parse('{"title":"图床迁移记","description":"","frontmatter":{"title":"图床迁移记"},"headers":[],"relativePath":"notes/cdn-migration.md","filePath":"notes/cdn-migration.md","lastUpdated":1791895356000}'),i={name:"notes/cdn-migration.md"};function p(a,e,d,c,r,l){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="图床迁移记" tabindex="-1">图床迁移记</h1><blockquote><p>图片这种东西，平时不出声，一出问题全是问题。</p></blockquote><h2 id="上一套图床" tabindex="-1">上一套图床</h2><p>旧站用的是对象存储，国内的 OSS 和 OBS 都开过。它没有不好用，只是对一个只放几十张图的个人站来说，重了：要实名，要绑域名，要配 HTTPS 证书，还要记着看资源包什么时候到期。账单不贵，但那种「总有一件事会到期」的感觉不好受。</p><p>真正让我下决心换的是删库。有一次整理桶的时候清掉了整个目录，站上所有图一夜之间全变成裂图，而对象存储那边没有可回溯的历史。图片是文章的一部分，把它们放在一个删了就没的地方，本身就是个设计问题。</p><h2 id="换成了什么" tabindex="-1">换成了什么</h2><p>现在是：<strong>一个公开的 GitHub 仓库放图，前面挂 jsDelivr 当 CDN</strong>。仓库里所有图片统一放在 <code>images/</code> 目录下，于是链接的形状是固定的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes rose-pine-dawn rose-pine-moon vp-code" tabindex="0"><code><span class="line"><span>https://cdn.jsdelivr.net/gh/yichen0808/Blog-images@main/images/&lt;文件名&gt;</span></span></code></pre></div><p>拆开看三段：<code>gh</code> 说明后面接的是 GitHub 仓库，<code>@main</code> 指定分支，后面就是仓库内的路径。这个形式的好处是它足够无聊——分支写死在 URL 里，不需要任何构建，往仓库里推一张图，链接当场就能用。</p><p>代价也说清楚：jsDelivr 在国内并不是永远通的，偶尔会慢，极端情况下会连不上。我接受它，是因为它免费、有缓存、而且换掉它的成本很低——链接的主体是 GitHub 的仓库路径，真要迁移，把前缀替换一遍就完了。</p><h2 id="缓存这件事值得单独说" tabindex="-1">缓存这件事值得单独说</h2><p>CDN 会缓存，这是它快的原因，也是它唯一会骗人的地方。</p><p><strong>用同名文件覆盖一张图，访问到的很可能还是旧的那张</strong>，因为缓存还没到期。想强制刷新要去 jsDelivr 的清除页面手动提交，一次能提交的条数还有上限。</p><p>所以我的习惯是：<strong>改图就直接换文件名</strong>，早先那些链接如果还留在文章里，就一起改掉。文件名带一点语义，比如 <code>cover-zhulin.jpg</code>、<code>book-santi.jpg</code>，改的时候顺手加个后缀或者换个编号。比起和缓存较劲，这个办法更省事。</p><h2 id="为什么图片另开一个仓库" tabindex="-1">为什么图片另开一个仓库</h2><p>这里有一个容易被忽略的前提：<strong>图床仓库是公开的，源码仓库是私有的</strong>。</p><p>文章里的图片本来就要被所有人看到，公开它没有任何损失。但 <code>docs</code> 目录里躺着的是草稿、写着半截的笔记和还没发布的想法，那些我不想被搜到。</p><p>分开之后，两边各得其所：图能直接发给朋友看、能被别人的文章引用，源码该藏的继续藏着。顺带还有一个好处——图片库的提交历史很干净，清一色是「加了哪张图、删了哪张图」，不会和文章改动混在一起。</p><h2 id="图得先压过再传" tabindex="-1">图得先压过再传</h2><p>最后是一条纪律：<strong>上传前先压</strong>。</p><p>原图动辄五到十兆，而这里最重的一张背景图实际也就用到一千多像素宽。我的流程是先把长边压到一千六以内，照片一律导出成 JPEG（quality 82 上下，带 progressive），只有需要透明通道的图标才留给 PNG 或者直接上 SVG，导出时看一眼体积——超过五百 KB 就再压一次。</p><p>这件事没有技术含量，但它决定了三年后这个仓库是二百兆还是两个 G。CDN 只负责送得快，不负责让文件变小。</p>',22)])])}const _=t(i,[["render",p]]);export{h as __pageData,_ as default};
